export type TemplateType = "game-card" | "pros-cons" | "score" | "ranking" | "versus";

export type FormatType = "horizontal" | "vertical";

export type ThemeType = "dark" | "colorful" | "minimal";

export type GameCardData = {
  gameName: string;
  publisher: string;
  year: string;
  players: string;
  duration: string;
  age: string;
  difficulty: number;
  categories: string;
  coverImage: string;
  verdict: string;
};

export type ProsConsData = {
  gameName: string;
  pros: string[];
  cons: string[];
  verdict: string;
};

export type ScoreData = {
  gameName: string;
  fun: number;
  replayability: number;
  interaction: number;
  production: number;
  teachability: number;
  finalScore: number;
  finalLabel: string;
  animationDuration: number;
};

export type RankingItem = {
  position: number;
  name: string;
  comment: string;
};

export type RankingData = {
  title: string;
  items: RankingItem[];
};

export type VersusData = {
  gameA: string;
  gameB: string;
  durationA: string;
  durationB: string;
  difficultyA: number;
  difficultyB: number;
  interactionA: number;
  interactionB: number;
  bestForA: string;
  bestForB: string;
  winner: string;
};

export type TemplateDataMap = {
  "game-card": GameCardData;
  "pros-cons": ProsConsData;
  score: ScoreData;
  ranking: RankingData;
  versus: VersusData;
};

export type ProjectState = {
  template: TemplateType;
  format: FormatType;
  theme: ThemeType;
  data: TemplateDataMap;
};

export const TEMPLATE_LABELS: Record<TemplateType, string> = {
  "game-card": "Ficha de juego",
  "pros-cons": "Pros y contras",
  score: "Puntuación final",
  ranking: "Ranking Top",
  versus: "Versus",
};

export const FORMAT_SIZES: Record<FormatType, { width: number; height: number; label: string }> = {
  horizontal: { width: 1920, height: 1080, label: "Horizontal 16:9" },
  vertical: { width: 1080, height: 1920, label: "Vertical 9:16" },
};
